#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    fn tmp_root() -> std::path::PathBuf {
        let mut p = std::env::temp_dir();
        p.push(format!("hmcp_test_{}", std::process::id()));
        fs::create_dir_all(&p).unwrap();
        p.canonicalize().unwrap()
    }

    // ---- path confinement (V7) ----

    #[test]
    fn confine_allows_relative_write_leaf() {
        let root = tmp_root();
        let got = confine_path(&root, "out/mesh.bgeo", true).unwrap();
        assert!(got.starts_with(&root.to_string_lossy().to_string()));
    }

    #[test]
    fn confine_rejects_parent_escape() {
        let root = tmp_root();
        assert!(confine_path(&root, "../evil.txt", true).is_err());
    }

    #[test]
    fn confine_rejects_absolute_outside() {
        let root = tmp_root();
        let outside = if cfg!(windows) { "C:\\Windows\\System32\\drivers\\etc\\hosts" } else { "/etc/passwd" };
        assert!(confine_path(&root, outside, false).is_err());
    }

    #[test]
    fn confine_read_requires_existing() {
        let root = tmp_root();
        assert!(confine_path(&root, "does_not_exist.ply", false).is_err());
    }

    // ---- junction-inside-root escape (V7 — the Windows tunneling vector the audit flagged as
    // untested). A directory junction placed inside the working dir that points OUTSIDE it must not
    // let a read or write tunnel out: `canonicalize` resolves the junction to its target, so the
    // `starts_with(root)` check fails. Junctions (mklink /J) need no admin, unlike symlinks. ----
    #[cfg(windows)]
    #[test]
    fn confine_rejects_junction_escaping_root() {
        use std::sync::atomic::{AtomicU32, Ordering};
        static CTR: AtomicU32 = AtomicU32::new(0);
        let uniq = |tag: &str| -> std::path::PathBuf {
            let n = CTR.fetch_add(1, Ordering::Relaxed);
            let mut p = std::env::temp_dir();
            p.push(format!("hmcp_jctest_{}_{}_{}", std::process::id(), n, tag));
            fs::create_dir_all(&p).unwrap();
            p.canonicalize().unwrap()
        };
        let root = uniq("root");
        let outside = uniq("outside");
        fs::write(outside.join("secret.txt"), b"top secret").unwrap();

        // a junction INSIDE root that points OUTSIDE it
        let link = root.join("escape");
        let made = std::process::Command::new("cmd")
            .args(["/C", "mklink", "/J", link.to_str().unwrap(), outside.to_str().unwrap()])
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        assert!(made, "mklink /J failed — cannot exercise the junction-escape gate");

        // read + write through the junction must both be REJECTED
        assert!(
            confine_path(&root, "escape/secret.txt", false).is_err(),
            "read through an escaping junction was NOT rejected"
        );
        assert!(
            confine_path(&root, "escape/planted.txt", true).is_err(),
            "write through an escaping junction was NOT rejected"
        );
        // sanity: a genuine path inside root is still allowed
        fs::write(root.join("ok.txt"), b"fine").unwrap();
        assert!(confine_path(&root, "ok.txt", false).is_ok());

        // cleanup: remove the junction link FIRST (rmdir removes the reparse point, not the target),
        // so remove_dir_all never recurses through it into `outside`.
        let _ = std::process::Command::new("cmd").args(["/C", "rmdir", link.to_str().unwrap()]).status();
        let _ = fs::remove_dir_all(&root);
        let _ = fs::remove_dir_all(&outside);
    }

    #[test]
    fn confine_rejects_parent_dir_traversal_in_tail() {
        // Regression for the `confine_path` tail-walk bug: a `..` reaching the not-yet-existing
        // tail used to be silently dropped (Path::file_name() is None for `..`), redirecting a
        // write above/outside the intended target. The security property under test — a `..`
        // traversal that would leave the working dir is REJECTED, never silently rewritten — must
        // hold on every platform. (On Linux the fix's ParentDir bail catches it; on Windows the
        // lexical `..` collapse makes `starts_with(root)` catch it. Either way: reject.) write=true
        // is the vulnerable mode; read=false already fails the metadata() existence check.
        let root = tmp_root();
        assert!(confine_path(&root, "out.bgeo", true).is_ok(), "clean leaf must resolve");
        for bad in [
            "newdir/../../etc/passwd",
            "newdir/../../../../../../etc/passwd",
            "a/b/../../../../tmp/pwned.bgeo",
            "../escape.bgeo",
            "../../etc/passwd",
        ] {
            assert!(confine_path(&root, bad, true).is_err(), "must reject traversal '{bad}'");
        }
    }

    // ---- typed validation (V6 clamps, unknown-key rejection, enums, required) ----

    #[test]
    fn validate_clamps_numeric_to_ceiling() {
        let root = tmp_root();
        let tool = ToolDef { name: "t", category: "_test", description: "", params: vec![Param::opt("n", Kind::Int { min: 1, max: 10 }, "")] };
        let out = tool.validate(&json!({ "n": 10_000 }), &root).unwrap();
        assert_eq!(out["n"], json!(10));
    }

    #[test]
    fn validate_rejects_unknown_param() {
        let root = tmp_root();
        let tool = ToolDef { name: "t", category: "_test", description: "", params: vec![] };
        assert!(tool.validate(&json!({ "smuggled": 1 }), &root).is_err());
    }

    #[test]
    fn validate_enforces_required() {
        let root = tmp_root();
        let tool = ToolDef { name: "t", category: "_test", description: "", params: vec![Param::req("x", Kind::Str, "")] };
        assert!(tool.validate(&json!({}), &root).is_err());
    }

    #[test]
    fn validate_enum_rejects_out_of_set() {
        let root = tmp_root();
        let tool = ToolDef { name: "t", category: "_test", description: "", params: vec![Param::opt("m", Kind::Enum(&["a", "b"]), "")] };
        assert!(tool.validate(&json!({ "m": "c" }), &root).is_err());
        assert!(tool.validate(&json!({ "m": "a" }), &root).is_ok());
    }

    // ---- OpList (the batch envelope's ops param) structural validation ----

    #[test]
    fn oplist_accepts_wellformed_ops() {
        let root = tmp_root();
        let p = Param::req("ops", Kind::OpList, "");
        let good = json!([
            { "name": "scene_info" },
            { "name": "set_frame", "arguments": { "frame": 5 } }
        ]);
        let out = validate_value(&p, &good, &root).unwrap();
        assert_eq!(out, good, "a well-formed ops list is returned as-is");
    }

    #[test]
    fn oplist_rejects_maxitems_overflow() {
        let root = tmp_root();
        let p = Param::req("ops", Kind::OpList, "");
        let too_many: Vec<Value> = (0..65).map(|_| json!({ "name": "scene_info" })).collect();
        assert!(validate_value(&p, &json!(too_many), &root).is_err(), "65 ops must be rejected (max 64)");
        // boundary: exactly 64 is accepted
        let ok64: Vec<Value> = (0..64).map(|_| json!({ "name": "scene_info" })).collect();
        assert!(validate_value(&p, &json!(ok64), &root).is_ok(), "exactly 64 ops must be accepted");
    }

    #[test]
    fn oplist_rejects_empty() {
        let root = tmp_root();
        let p = Param::req("ops", Kind::OpList, "");
        assert!(validate_value(&p, &json!([]), &root).is_err(), "an empty ops list must be rejected (min 1)");
    }

    #[test]
    fn oplist_rejects_nested_batch() {
        let root = tmp_root();
        let p = Param::req("ops", Kind::OpList, "");
        let nested = json!([{ "name": "scene_info" }, { "name": "batch", "arguments": {} }]);
        assert!(validate_value(&p, &nested, &root).is_err(), "an op named 'batch' must be rejected (no nesting)");
    }

    #[test]
    fn oplist_rejects_non_string_name() {
        let root = tmp_root();
        let p = Param::req("ops", Kind::OpList, "");
        assert!(validate_value(&p, &json!([{ "name": 123 }]), &root).is_err(), "a non-string op name must be rejected");
        assert!(validate_value(&p, &json!([{ "name": "" }]), &root).is_err(), "an empty op name must be rejected");
        assert!(validate_value(&p, &json!([{ "arguments": {} }]), &root).is_err(), "an op with no name must be rejected");
        assert!(validate_value(&p, &json!([{ "name": "scene_info", "extra": 1 }]), &root).is_err(), "an op with an unexpected key must be rejected");
        assert!(validate_value(&p, &json!([{ "name": "scene_info", "arguments": 5 }]), &root).is_err(), "non-object arguments must be rejected");
    }

    #[test]
    fn batch_is_in_catalog_and_unique() {
        let catalog = mvp_catalog();
        let batch = catalog.iter().find(|t| t.name == "batch").expect("batch must be in the catalog");
        // ops is a required OpList param; stop_on_error is an optional Bool.
        assert!(matches!(batch.params.iter().find(|p| p.name == "ops").map(|p| &p.kind), Some(Kind::OpList)));
        assert!(batch.params.iter().any(|p| p.name == "stop_on_error" && matches!(p.kind, Kind::Bool)));
    }

    // ---- the load-bearing invariant: no RCE primitives in the public catalog ----

    #[test]
    fn catalog_never_exposes_rce_tools() {
        let names: Vec<&str> = mvp_catalog().iter().map(|t| t.name).collect();
        for banned in ["exec", "node_op", "wrangle", "heightfield_op"] {
            assert!(!names.contains(&banned), "catalog must never expose '{banned}'");
        }
    }

    /// Semantic companion to the name-based ban above: the ONLY param Kind that may carry code text is
    /// `Kind::VexSnippet` (executor-validated, allowlist-first, loop-free, no I/O). No tool may ship a
    /// bare non-VexSnippet param whose name implies code (code/snippet/vex/expr/…), and every VexSnippet
    /// must declare a known validation profile. This keeps "no arbitrary code execution" a build-enforced
    /// invariant, not a naming convention: any code-carrying param is provably the validated Kind.
    #[test]
    fn safe_vex_is_the_only_code_path() {
        const CODEY: [&str; 6] = ["code", "snippet", "vex", "expr", "vexpression", "vexcode"];
        for t in mvp_catalog() {
            for p in &t.params {
                match &p.kind {
                    Kind::VexSnippet { profile } => assert!(
                        ["attrib_v1"].contains(profile),
                        "tool '{}' param '{}' uses unknown VexSnippet profile '{}'",
                        t.name, p.name, profile
                    ),
                    _ => assert!(
                        !CODEY.contains(&p.name),
                        "tool '{}' ships a code-named param '{}' that is NOT a VexSnippet — code text \
                         must route through the validated VexSnippet Kind (executor-validated)",
                        t.name, p.name
                    ),
                }
            }
        }
    }

    /// The `vex_reference` `topic` Enum (the gateway schema gate, here in tools.rs) MUST stay in sync
    /// with `native::VEX_TOPICS` (the runtime topic->guide-section map). If they drift, a topic the
    /// runtime serves is rejected by the schema before it arrives (or vice-versa) — exactly the
    /// `topic=surface` bug this test was added for. Add a new topic to BOTH or neither.
    #[test]
    fn vex_reference_topic_enum_matches_vex_topics() {
        let catalog = mvp_catalog();
        let vr = catalog.iter().find(|t| t.name == "vex_reference").expect("vex_reference in catalog");
        let topic = vr.params.iter().find(|p| p.name == "topic").expect("vex_reference has a topic param");
        let choices = match &topic.kind {
            Kind::Enum(c) => *c,
            _ => panic!("vex_reference `topic` must be an Enum"),
        };
        let mut choices: Vec<&str> = choices.to_vec();
        let mut keys: Vec<&str> = crate::native::VEX_TOPICS.iter().map(|(k, _)| *k).collect();
        choices.sort_unstable();
        keys.sort_unstable();
        assert_eq!(
            choices, keys,
            "vex_reference `topic` Enum (tools.rs) drifted from native::VEX_TOPICS keys — add the topic to BOTH"
        );
    }

    /// The gateway's VexSnippet CONSERVATIVE PRE-CHECK (`validate_value`) must reject the hard escapes
    /// and bounds before a snippet ever reaches the executor's authoritative allowlist validator — the
    /// "both layers reject" guarantee for the one code-carrying param. The executor half is covered by
    /// `vex_validator.py`'s red-team corpus; this pins the gateway half so the fast typed pre-check can
    /// never silently regress (red-team RT-2 / prod-readiness item 5: the pre-check was untested).
    #[test]
    fn vexsnippet_precheck_rejects_hard_escapes() {
        let wd = std::path::Path::new(".");
        let p = Param::req("code", Kind::VexSnippet { profile: "attrib_v1" }, "safe-VEX");
        // a clean snippet passes the conservative pre-check (the executor still validates it authoritatively)
        assert!(validate_value(&p, &json!("f@x = 0;"), wd).is_ok(), "clean snippet must pass the pre-check");
        // every hard escape / bound must reject at the gateway, independent of the executor
        let rejects = [
            json!(""),                                // empty
            json!("   "),                             // whitespace-only
            json!("f@x = `system(\"x\")`;"),          // backtick hscript escape
            json!("#include \"x\"\n@x = 1;"),         // preprocessor
            json!("s@n = $HIP;"),                     // hscript / env var
            json!("f@x = 0; // \u{00e9}"),            // non-ASCII (homoglyph smuggling)
            json!(123),                               // not a string
            json!("f@x = 0;".repeat(400)),            // ~2400 chars > 2048 cap
        ];
        for bad in rejects {
            assert!(validate_value(&p, &bad, wd).is_err(), "pre-check must reject {bad:?}");
        }
    }

    // ---- catalog is unique, and dumps to reference/catalog.json for the offline doc generator ----

    #[test]
    fn catalog_names_are_unique() {
        let catalog = mvp_catalog();
        let mut seen = std::collections::HashSet::new();
        for t in &catalog {
            assert!(seen.insert(t.name), "duplicate tool name in catalog: '{}'", t.name);
        }
    }

    /// Serialize the whole typed catalog to `reference/catalog.json` — the authoritative,
    /// machine-readable twin of `reference/NODE_REFERENCE.md`. The offline Python generator
    /// consumes this (never re-parses this .rs), so the docs it emits are provably whatever the
    /// compiled boundary contains. Run with `cargo test emit_catalog_json`.
    #[test]
    fn emit_catalog_json() {
        let catalog = mvp_catalog();
        let tools: Vec<Value> = catalog.iter().map(|t| t.describe()).collect();
        let doc = json!({
            "note": "Authoritative typed tool catalog dumped from gateway/src/tools.rs (the security boundary). Generated by `cargo test emit_catalog_json`; do not hand-edit.",
            "houdini_version": "21.0.671",
            "tool_count": tools.len(),
            "tools": tools,
        });
        let mut path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        path.pop(); // gateway/ -> repo root
        path.push("reference");
        path.push("catalog.json");
        let body = serde_json::to_string_pretty(&doc).unwrap() + "\n";
        fs::write(&path, body).unwrap_or_else(|e| panic!("write {}: {e}", path.display()));
        eprintln!("wrote {} tools -> {}", tools.len(), path.display());
    }
}
